<?php declare(strict_types=1); namespace App\Web\Admin\Role\Delete; use App\Role\RoleRepository; use Psr\Http\Message\{ResponseFactoryInterface,ResponseInterface}; use Yiisoft\Router\HydratorAttribute\RouteArgument; use Yiisoft\Router\UrlGeneratorInterface; final readonly class Action{public function __construct(private RoleRepository $roles,private ResponseFactoryInterface $factory,private UrlGeneratorInterface $url){} public function __invoke(#[RouteArgument]int $id):ResponseInterface{$r=$this->roles->findById($id);if($r)$this->roles->delete($r);return $this->factory->createResponse(302)->withHeader('Location',$this->url->generate('admin/role/index'));}}
